    : $json.questionType === 'Multiple Choice'
    ? '• Select all correct options from the dropdown below and submit.\n• You will get an instant private reply with feedback!'
    : '• Click one of the buttons below (A, B, C, or D) to submit your answer.\n• You will get an instant private reply with feedback!'
}\n• Official breakdown posted in **3 hours**.`,
    "components": $json.questionType === 'Short Answer' 
      ? [] 
      : $json.questionType === 'Multiple Choice'
      ? [
          {
            "type": 1,
            "components": [
              {
                "type": 3,
                "custom_id": "quiz_select_multi",
                "options": $json.options.map((opt, i) => ({
                  "label": opt.substring(0, 25),
                  "value": String.fromCharCode(65 + i),
                  "description": opt.substring(0, 50)
                })),
                "placeholder": "Choose your answers...",
                "min_values": 1,
                "max_values": 4
              }
            ]
          }
