const catalogData = $('Catalog').first().json;
const searchResults =$input.first().json.results || [];

// Extract 100% real, verified URLs from search response
const verifiedUrls = searchResults.map(r => r.url).filter(Boolean);

// Weighted format selection (50% Single Choice, 30% Multiple Choice, 20% Short Answer)
const randomValue = Math.random();
let selectedFormat = "Single Choice";
if (randomValue > 0.8) {
  selectedFormat = "Short Answer";
} else if (randomValue > 0.5) {
  selectedFormat = "Multiple Choice";
}

return [
  {
    json: {
      timestamp: new Date().toISOString(),
      sourceType: "web_topic",
      sourceName: catalogData.sourceName,
      searchTopic: $('Generate Topics').first().json.content?.parts?.[0]?.text || catalogData.searchTopic,
      verifiedUrls: verifiedUrls,
      category: catalogData.category,
      sourceCitation: `${catalogData.sourceName} - Web Reference`,
      targetFormat: selectedFormat
    }
  }
];

